from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    grid = [list(lines[i + 1]) for i in range(n)]

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                yield nr, nc

    def get_room(cells, visited_set, bfs_queue):
        # BFS to find all cells in a room
        room_cells = []
        queue = deque()
        queue.append((cells[0][0], cells[0][1]))
        visited = set((cells[0]))

        while queue:
            r, c = queue.popleft()
            room_cells.append((r, c))
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited_set and grid[nr][nc] == '.':
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return room_cells

    while True:
        changed = False
        seen = set()

        for i in range(n):
            for j in range(m):
                if (i, j) in seen or grid[i][j] == '*':
                    continue

                # Find all cells in this room
                queue = deque([(i, j)])
                queue_set = set([(i, j)])
                seen.add((i, j))

                while queue:
                    r, c = queue.popleft()

                    for nr, nc in get_neighbors(r, c):
                        if (nr, nc) not in queue_set and grid[nr][nc] == '.':
                            queue_set.add((nr, nc))
                            seen.add((nr, nc))
                            queue.append((nr, nc))

                # Compute bounding box
                if not queue_set:
                    continue

                rows = [r for r, c in queue_set]
                cols = [c for r, c in queue_set]

                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                # Fill the bounding box
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        if grid[r][c] == '*':
                            grid[r][c] = '.'
                            changed = True

        if not changed:
            break

    return '\n'.join(''.join(row) for row in grid)
