    # dp[i][j][k] = max length of LCS using first i chars of s1, j chars of s2, ending with k chars of virus matched

    # Optimization: flatten to 2D arrays for k, since many k states are unreachable
    dp = [[[0] * v for _ in range(m + 1)] for _ in range(n + 1)]
    parent = [[[None] * v for _ in range(m + 1)] for _ in range(n + 1)]

