from collections import defaultdict

def solve_problem(s, queries):
    # Process queries in reverse order
    # final_table[d] = (value, length) where digit d eventually becomes this value after all queries
    final_table = {}

    for i in range(9, -1, -1):
        final_table[i] = (i % MOD, 1)

    for i in range(len(queries) - 1, -1, -1):
        d_query, t_query = queries[i]
        d_val = int(d_query)

        t_result = 0
        t_len = 0

        if not t_query:
            # Replacement is empty string
            final_table[d_val] = (0, 0)
        else:
            for c in t_query:
                c_val = int(c)
                val, length = final_table[c_val]
                t_result = (t_result * (10 ** length) % MOD + val) % MOD
                t_len = (t_len + length) % (MOD - 1)  # Use MOD-1 for length due to Fermat's little theorem

            final_table[d_val] = (t_result, t_len)

    # Now compute the result for the initial string
    result_val = 0
    for c in s:
        c_val = int(c)
        val, length = final_table[c_val]
        result_val = (result_val * (10 ** length) % MOD + val) % MOD

    return result_val

def solution(input_data):
    lines = input_data.strip().split('\n')
    s = lines[0]
    n = int(lines[1])

    queries = []
    for i in range(2, 2 + n):
