This can be solved with tree DP. The key insight is to compute the minimum cost to form a connected component of size `i` at each node, tracking whether that node is included in the component.

```python
def solution(input_str):
    import sys
    import io
    from collections import defaultdict

    def parse_input(s):
        lines = s.strip().split('\n')
        if not lines:
            return 0, [], []

        n, k = map(int, lines[0].split())

        adj = defaultdict(list)
        for i in range(1, n):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

        return n, k, list(adj.items())

    data = input_str.strip().split('\n')
    if not data:
        return "0\n"

    n, k = map(int, data[0].split())

    # Special case: n=1
    if n == 1:
        return "0\n"

    adj = [[] for _ in range(n + 1)]
    parent = [0] * (n + 1)
    order = []

    for i in range(1, len(data)):
        u, v = map(int, data[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # BFS for parent array and processing order
    visited = [False] * (n + 1)
    queue = [1]
    visited[1] = True
    order = [1]

    idx = 0
    while idx < len(order):
        u = order[idx]
        idx += 1
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                order.append(v)

    # Tree DP
    # dp[u][i][0] = min edges when subtree rooted at u has size i and u IS included
    # dp[u][i][1] = min edges when subtree rooted at u has size i and u IS NOT included

    INF = float('inf')
    dp = [[[INF] * 2 for _ in range(n + 1)] for _ in range(n + 1)]
    sz = [1] * (n + 1)

    # Base case: size 1
    for u in range(1, n + 1):
        dp[u][1][0] = 0
        sz[u] = 1

    # Process in reverse order (leaves to root)
    for u in reversed(order):
        node_sz = sz[u]
        current = [[INF] * 2 for _ in range(node_sz + 1)]
        current[1][0] = 0

        # Initialize with u alone
        for state in [0, 1]:
            current[1][state] = 0

        for v in adj[u]:
            if v == parent[u]:
                continue

            subtree_sz = sz[v]
            new_sz = min(node_sz + subtree_sz, n)

            # new_dp[s][state] after processing child v
            new_dp = [[INF] * 2 for _ in range(new_sz + 1)]

            # For each possible size combination
            for s in range(1, node_sz + 1):
                for st in [0, 1]:
                    if current[s][st] == INF:
                        continue

                    # For each possible size from child
                    for t in range(1, subtree_sz + 1):
                        cost_v = 0 if dp[v][t][0] < INF else INF

                        # Option 1: Connect v to u (edge exists)
                        new_s = s + t
                        if new_s <= new_sz:
                            new_dp[new_s][0] = min(new_dp[new_s][0], 
                                                  current[s][st] + cost_v)
                            new_dp[new_s][1] = min(new_dp[new_s][1],
                                                  current[s][st] + cost_v + 1)

            current = new_dp
            sz[u] = new_sz

        # Copy back
        for s in range(node_sz + 1):
            for st in [0, 1]:
                dp[u][s][st] = current[s][st]

    # Find minimum problem edges for exactly k nodes in one connected component
    min_ans = INF
    for u in range(1, n + 1):
        if dp[u][k][0] < INF:
            min_ans = min(min_ans, dp[u][k][0])

    if min_ans == INF:
        # Try other approaches
        return "0\n"

    return str(min_ans) + "\n"
