            if tc in t_to_s:
                if t_to_s[tc] != sc:
                    return False

            s_to_t[sc] = tc
            t_to_s[tc] = sc

        return True

    for i in range(n - m + 1):
        S_sub = S[i:i+m]
        if can_encode(S_sub):
            results.append(i + 1)  # 1-indexed

    results.sort()

    output = str(len(results)) + '\n'
    if results:
        output += ' '.join(map(str, results)) + '\n'
