    # Precompute Fibonacci numbers up to 10^18
    fibs = [1, 2]
    while fibs[-1] <= 10**18:
        fibs.append(fibs[-1] + fibs[-2])
    fibs = fibs[:-1]  # Remove the one exceeding 10^18

    def count_decompositions(n, start_idx):
        if n == 0:
            return 1
        if n < 0:
            return 0

        count = 0
        # Find the largest fib <= n at or after start_idx
        i = start_idx
        while i < len(fibs) and fibs[i] <= n:
            # Case 1: don't include fibs[i]
            count += count_decompositions(n, i + 1)
            # Case 2: include fibs[i]
            count += count_decompositions(n - fibs[i], i + 1)
            i += 1
