        valid_fibs = [f for f in fibs if f <= n]

        def dp(idx, remaining):
            if remaining == 0:
                return 1
            if idx == len(valid_fibs):
                return 0

            # Don't take valid_fibs[idx]
            res = dp(idx + 1, remaining)

            # Take valid_fibs[idx]
            res += dp(idx + 1, remaining - valid_fibs[idx])

            return res

