    if n == 1:
        # Any single number from l to r is a valid progression
        return str(r - l + 1)

    if n == 2:
        # Any pair of distinct numbers forms a geometric progression
        # Number of choices = (r-l+1) * (r-l)
        return str((r - l + 1) * (r - l))

    # For n >= 3, we need to find sequences where a2/a1 = a3/a2 = ... = d
    # This means a[i+1] = a[i] * d
    # For integer sequences, d can be rational

    if n == 3:
        count = 0
        for a1 in range(l, r + 1):
            for a2 in range(l, r + 1):
                if a2 == a1:
                    continue
                # Check if a3 = a2^2 / a1 is integer and valid
                if a2 * a2 % a1 == 0:
                    a3 = (a2 * a2) // a1
                    if l <= a3 <= r and a3 != a1 and a3 != a2:
                        count += 1
        return str(count)

    # For n >= 4, need to find integer sequences with valid ratio
    # Since n can be up to 10^7, we need a smarter approach
    # Count based on valid ratios p/q and valid multiplier m

    count = 0

    # Enumerate coprime pairs (p, q) and count valid progressions
    for p in range(1, 50):
        for q in range(1, 50):
            if p == q:
                continue  # ratio = 1 means all elements equal
            if __import__('math').gcd(p, q) != 1:
                continue

            # For ratio p/q, the terms are:
            # m*q^(n-1), m*q^(n-2)*p, m*q^(n-3)*p^2, ..., m*p^(n-1)
            # For all terms to be integers: m must be divisible by q^(n-1)

            pn = p**(n-1)
            qn = q**(n-1)

            min_pow = min(pn, qn)
            max_pow = max(pn, qn)

            if min_pow == 0:
                continue

            # m must be in range [l/max_pow, r/min_pow]
            lower = (l + max_pow - 1) // max_pow
            upper = r // min_pow

            if upper >= lower:
                count += (upper - lower + 1)

    return str(count)
