Looking at this problem, I need to find the largest base `b` (where 1 < b < x) such that there exists a "Rotatable Number" of length n under base b. 

The key insight is that for a rotatable number of length n to exist in base b, there must be a prime `p` such that:
1. The number `b^n - 1` is divisible by `p`
2. The multiplicative order of `b` modulo `p` equals exactly `n`

This means `n` must divide `p-1` (since by Fermat's Little Theorem, `b^(p-1) ≡ 1 (mod p)` for any b coprime to p), and we need to find a base `b` that has order exactly `n` modulo `p`.

```python
def is_prime(num):
    """Check if num is prime"""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def pow_mod(base, exp, mod):
    """Compute (base^exp) % mod efficiently"""
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

def get_order(a, n, mod):
    """Check if a has multiplicative order exactly n modulo mod"""
    # Order must divide n
    if pow_mod(a, n, mod) != 1:
        return False

    # Check all proper divisors
    for d in range(1, n):
        if n % d == 0 and pow_mod(a, d, mod) == 1:
            return False

    return True

def solution(input_str):
    """Find the largest base b (1 < b < x) where a rotatable number of length n exists"""
    import sys

    n, x = map(int, input_str.strip().split())

    # If n <= 1, no valid solution exists
    if n <= 1:
        return "-1\n"

    # We need b < x and ord_p(b) = n, which requires p > n
    # So if x <= n + 1, no solution exists
    if x <= n + 1:
        return "-1\n"

    # Search for the largest b starting from x-1
    for b in range(x - 1, 1, -1):
        # Find a prime p where ord_p(b) = n
        # This requires n | (p-1) for some prime p

        # Check primes where p-1 is divisible by n
        found = False
        p_check = min(b + 1, x)

        # Search for valid primes
        field = 100000  # Reasonable search limit for primes
        end = min(p_check - 1, x)
        start = max(end - field + 1, b + 1)

        for p in range(end, start - 1, -1):
            if is_prime(p) and (p - 1) % n == 0:
                if get_order(b, (p - 1) // n, p):
                    found = True
                    break

        if found:
            return str(b) + "\n"

    # Check for edge cases with small primes
    for b in range(min(x - 1, 7), 1, -1):
        for p in [3, 5, 7]:
            if is_prime(p) and (p - 1) % n == 0:
                if get_order(b, (p - 1) // n, p):
                    return str(b) + "\n"

    return "-1\n"
